import React, { useState } from "react";
import ChartistGraph from "react-chartist";
import {
  Card,
  Container,
  Row,
  Col,
  Form,
  Button,
} from "react-bootstrap";

function History() {
  // 1. State สำหรับ Filter และข้อมูลกราฟ
  const [cameraId, setCameraId] = useState("CAM01");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [data, setData] = useState({ labels: [], series: [] });
  const [loading, setLoading] = useState(false);

  // 2. ฟังก์ชันดึงข้อมูลประวัติจาก API
  const handleFetchHistory = async () => {
    if (!startDate || !endDate) {
      alert("กรุณาเลือกวันที่เริ่มต้นและสิ้นสุด");
      return;
    }
    
    setLoading(true);
    try {
      const response = await fetch(
        `http://localhost:3000/api/history?cameraId=${cameraId}&startDate=${startDate}&endDate=${endDate}`
      );
      const result = await response.json();
      
      if (result.labels && result.labels.length > 0) {
        setData(result);
      } else {
        alert("ไม่พบข้อมูลในช่วงเวลาที่เลือก");
        setData({ labels: [], series: [] });
      }
    } catch (err) {
      console.error("Fetch History Error:", err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container fluid>
      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">Search Passenger History</Card.Title>
              <p className="card-category">เลือกจุดจอดและช่วงวันที่เพื่อดูสถิติย้อนหลัง</p>
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md="3">
                  <Form.Group>
                    <label>Select Station</label>
                    <Form.Control 
                      as="select" 
                      value={cameraId} 
                      onChange={(e) => setCameraId(e.target.value)}
                    >
                      <option value="CAM01">วิศวะ (CAM01)</option>
                      <option value="CAM02">วิทยาศาสตร์ (CAM02)</option>
                      <option value="CAM03">ศิลปศาสตร์ (CAM03)</option>
                      <option value="CAM04">PKY (CAM04)</option>
                    </Form.Control>
                  </Form.Group>
                </Col>
                <Col md="3">
                  <Form.Group>
                    <label>Start Date</label>
                    <Form.Control 
                      type="date" 
                      onChange={(e) => setStartDate(e.target.value)} 
                    />
                  </Form.Group>
                </Col>
                <Col md="3">
                  <Form.Group>
                    <label>End Date</label>
                    <Form.Control 
                      type="date" 
                      onChange={(e) => setEndDate(e.target.value)} 
                    />
                  </Form.Group>
                </Col>
                <Col md="3" className="d-flex align-items-end">
                  <Button 
                    className="btn-fill" 
                    variant="primary" 
                    onClick={handleFetchHistory}
                    disabled={loading}
                  >
                    {loading ? "Loading..." : "View History"}
                  </Button>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* แสดงกราฟเมื่อมีข้อมูล */}
      {data.labels.length > 0 && (
        <Row>
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h4">History Chart: {cameraId}</Card.Title>
                <p className="card-category">แสดงจำนวนคนในช่วงเวลาที่เลือก</p>
              </Card.Header>
              <Card.Body>
                <div className="ct-chart">
                  <ChartistGraph
                    data={data}
                    type="Line"
                    options={{
                      low: 0,
                      height: "300px",
                      showArea: true,
                      fullWidth: true,
                      axisX: { showGrid: false }
                    }}
                  />
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
